describe('Session Expiration After 30 Minutes of Inactivity', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should expire session after 30 minutes of inactivity and redirect to login', () => {
    // Login
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Wait for 30 minutes
    cy.intercept('api/session/refresh').as('sessionRefresh');
    cy.wait('@sessionRefresh', { timeout: 180000 });

    // Verify session expired and redirect to login
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="dashboard-header"]').should('not.exist');

    // Verify login page is displayed
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');
  });

  it('should not expire session if user is active', () => {
    // Login
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Perform an action to keep session alive
    cy.get('[data-testid="dashboard-header"]').click();
    cy.get('[data-testid="dashboard-header"]').click();

    // Verify session is still active
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Verify session does not expire after 30 minutes
    cy.intercept('api/session/refresh').as('sessionRefresh');
    cy.wait('@sessionRefresh', { timeout: 180000 });

    // Verify session is still active
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });
});
